import { defineConfig } from 'vite'

// The document is authored as real HTML in index.html, not generated by a
// framework, so Vite is only a bundler and a dev server here. Nothing in the
// entry graph may import three — a gate in scripts/gates.mjs enforces that.
/**
 * The whole stylesheet is under 10KB raw, and it is the only render-blocking
 * request on the page. Inlining it removes a full round trip from the critical
 * path: LCP measured 1286ms on Slow 4G with 4x CPU, of which 1285ms was render
 * delay against a 2ms TTFB. There is no second stylesheet to defer, so this is
 * the whole of "inline critical CSS" for this page.
 */
function inlineStylesheet() {
  return {
    name: 'inline-stylesheet',
    enforce: 'post',
    apply: 'build',
    transformIndexHtml: {
      order: 'post',
      handler(html, ctx) {
        if (!ctx.bundle) return html
        let out = html
        for (const [fileName, asset] of Object.entries(ctx.bundle)) {
          if (!fileName.endsWith('.css') || asset.type !== 'asset') continue
          const link = new RegExp(`<link[^>]+href="[^"]*${fileName.replace(/[.*+?^$()|[\]\\]/g, '\\$&')}"[^>]*>`)
          if (!link.test(out)) continue
          out = out.replace(link, `<style>${asset.source}</style>`)
          delete ctx.bundle[fileName]
        }
        return out
      },
    },
  }
}

export default defineConfig({
  plugins: [inlineStylesheet()],
  build: {
    target: 'es2022',
    cssCodeSplit: false,
    rollupOptions: {
      output: {
        // Keep the lazy 3D layer in its own named chunk so the size gate can
        // measure it separately from the entry.
        manualChunks(id) {
          if (id.includes('node_modules/three')) return 'three'
        },
      },
    },
  },
})
